INSERT INTO `tblPropers` (id,sort,lectionary,season,LiturgicalDate,color,theme,old,psalm,epistle,gospel,introit,hymnsug,note) VALUES 
(313, 1480, 'A', 'PENTECOST', 'The Day of Pentecost', 'Red', '<div><strong>The Risen Lord Jesus Pours Out the Holy Spirit</strong></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>The Lord took &quot;some of the Spirit&quot; that was on Moses &quot;and put it on the seventy elders&quot; of Israel (Num. 11:25), and they &quot;prophesied in the camp&quot; (Num. 11:26). In the same way, our risen Lord Jesus poured out His Holy Spirit at the Feast of Pentecost - the 50th day and the &quot;Eighth Sunday&quot; of Easter. When &quot;a sound like a mighty rushing wind&quot; and &quot;tongues as of fire appeared&quot; and rested on each of the 12 apostles, &quot;they were all filled with the Holy Spirit&quot; and proclaimed &quot;the mighty works of God&quot; (Acts 2:2-4, 11). The Lord Jesus grants this same Spirit to His Church on earth to proclaim Him glorified on the cross and risen victorious from the grave for us sinners. From His open heart, our crucified and risen Lord pours out His Holy Spirit in &quot;rivers of living water&quot; (John 7:38) and invites everyone who thirsts to come to Him and drink freely (John 7:37). Through this life-giving work of the Holy Spirit, we hear our pastors &quot;telling in our own tongues the mighty works of God&quot; (Acts 2:11), and &quot;everyone who calls upon the name of the Lord shall be saved&quot; (Acts 2:21).</div>', 'Num. 11:24–30', 'Psalm 25:1–15', 'Acts 2:1–21', 'John 7:37–39', '<div>INTROIT Ps. 104:24, 27–28, 30; antiphon: Liturgical Text </div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>Come, Holy Spirit, fill the hearts of the | faithful,* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and kindle in them the fire of your love. Alle- | luia.</strong> </div>\r\n\r\n<div>O LORD, how manifold are your works! In wisdom have you | made them all;* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>the earth is full of your | creatures. </strong></div>\r\n\r\n<div>These all | look to you,* </div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;to give them their food in due | season.</strong> </div>\r\n\r\n<div>When you give it to them, they gath- | er it up;* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>when you open your hand, they are filled with | good things. </strong></div>\r\n\r\n<div>When you send forth your Spirit, they are cre- | ated,* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and you renew the face | of the ground. </strong></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son* </strong></div>\r\n\r\n<div><strong>and to the Holy | Spirit; </strong></div>\r\n\r\n<div><strong>as it was in the be- | ginning,* </strong></div>\r\n\r\n<div><strong>is now, and will be forever. | Amen.</strong> </div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>Come, Holy Spirit, fill the hearts of the | faithful,* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and kindle in them the fire of your love. Alle- | luia.</strong></div>', '<div><strong>Day of Pentecost &nbsp;</strong></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>Entrance: 497 Come, Holy Ghost, God and Lord &nbsp;</div>\r\n\r\n<div>Of the Day: 502 Holy Spirit, the Dove Sent from Heaven &nbsp;</div>\r\n\r\n<div>Offertory: 650 Holy Spirit, Ever Dwelling &nbsp;Distribution:</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;496 Holy Spirit, Light Divine; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;768 To God the Holy Spirit Let</div>\r\n\r\n<div>Closing: 503 O Day Full of Grace</div>', '');
